import AVFoundation
import Testing
@testable import Closer

/// The bundled sounds are generated by `scripts/generate-notification-sounds.py`. These tests make
/// sure every sound the app offers is in the bundle and is a file iOS accepts for notifications,
/// and that custom sounds are stored where iOS finds them.
@MainActor
struct SoundLibraryTests {
    private let directory = TestAudio.temporaryFolder()

    private func makeLibrary() -> SoundLibrary {
        SoundLibrary(directory: directory, bundle: Bundle(for: PeopleViewModel.self))
    }

    // MARK: - Bundled sounds

    @Test func everyBundledSoundIsInTheAppBundle() {
        let library = makeLibrary()
        for sound in NotificationSound.bundled {
            #expect(library.url(for: sound) != nil, "\(sound.fileName ?? "") missing in the app bundle")
        }
    }

    @Test func theSystemDefaultHasNoFile() {
        #expect(makeLibrary().url(for: .standard) == nil)
    }

    @Test(arguments: NotificationSound.bundled)
    func bundledSoundIsLinearPCMAndAtMostThirtySeconds(_ sound: NotificationSound) throws {
        let url = try #require(makeLibrary().url(for: sound))
        let file = try AVAudioFile(forReading: url)
        let seconds = Double(file.length) / file.fileFormat.sampleRate
        #expect(seconds > 0.3)
        #expect(seconds <= 30)
        #expect(file.fileFormat.streamDescription.pointee.mFormatID == kAudioFormatLinearPCM)
    }

    // MARK: - Custom sounds

    @Test func defaultFolderIsLibrarySoundsWhereIOSLooksForNotificationSounds() {
        let path = SoundLibrary.defaultDirectory.standardizedFileURL.path(percentEncoded: false)
        #expect(path.hasSuffix("/Library/Sounds") || path.hasSuffix("/Library/Sounds/"))
    }

    @Test func importedSoundIsStoredUnderItsNotificationFileName() async throws {
        let library = makeLibrary()
        let custom = try await library.importSound(from: try TestAudio.tone(seconds: 3, name: "Lachen von Lea"))

        #expect(custom.name == "Lachen von Lea")
        #expect(abs(custom.duration - 3) < 0.01)
        #expect(library.customSounds == [custom])
        let url = try #require(library.url(for: custom.sound))
        #expect(url == directory.appending(path: custom.sound.fileName!))
    }

    @Test func customSoundsSurviveARestart() async throws {
        let custom = try await makeLibrary().importSound(from: try TestAudio.tone(seconds: 1))
        #expect(makeLibrary().customSounds == [custom])
    }

    @Test func deletedSoundIsGoneWithItsFile() async throws {
        let library = makeLibrary()
        let custom = try await library.importSound(from: try TestAudio.tone(seconds: 1))
        let url = try #require(library.url(for: custom.sound))

        try library.delete(custom.id)

        #expect(library.customSounds.isEmpty)
        #expect(library.url(for: custom.sound) == nil)
        #expect(!FileManager.default.fileExists(atPath: url.path()))
        #expect(makeLibrary().customSounds.isEmpty)
    }

    @Test func failedImportAddsNothing() async throws {
        let library = makeLibrary()
        let text = directory.appending(path: "notiz.m4a")
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        try Data("keine Musik".utf8).write(to: text)

        await #expect(throws: (any Error).self) { try await library.importSound(from: text) }
        #expect(library.customSounds.isEmpty)
    }
}
